      'summary' (default)  -> Dict with employee_id, overall_rating (float), goals_status
      'detailed'           -> Dict with ALL CSV columns, with correct types
      'department'         -> Dict { department: { 'avg_rating': float, 'count': int }, ... }
    Returns None if no result or employee not found (summary/detailed), or if no data.
    '''
    # Define column type mappings
    FLOAT_FIELDS = {'overall_rating'}
    INT_FIELDS = {'technical_score', 'communication_score', 'teamwork_score', 'leadership_score'}
    CSV_FILE = 'performance_reviews.csv'

    # Read all rows
    try:
        with open(CSV_FILE, newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            data = list(reader)
    except FileNotFoundError:
        return None

    if report_type == 'department' and employee_id is None:
        # Department aggregation
        depts = {}
        for row in data:
            dept = row['department']
            rating = row.get('overall_rating')
            # If overall_rating is empty, skip
            try:
                rating_value = float(rating)
            except (ValueError, TypeError):
                continue
            if dept not in depts:
                depts[dept] = {'ratings': [], 'count': 0}
            depts[dept]['ratings'].append(rating_value)
            depts[dept]['count'] += 1
        # Build result
        result = {}
        for dept, values in depts.items():
            ratings = values['ratings']
            count = values['count']
            avg = sum(ratings) / count if count > 0 else 0.0
            result[dept] = {'avg_rating': avg, 'count': count}
        return result

    else:
        # summary or detailed for a given employee
        for row in data:
            if row.get('employee_id') == employee_id:
                if report_type == 'summary':
                    try:
                        rating = float(row['overall_rating'])
                    except (ValueError, TypeError):
                        rating = 0.0
                    return {
                        'employee_id': row['employee_id'],
                        'overall_rating': rating,
                        'goals_status': row['goals_status'],
                    }
                elif report_type == 'detailed':
                    # Build dict with correct types
                    detailed = {}
                    for k, v in row.items():
                        if k in FLOAT_FIELDS:
                            try:
                                detailed[k] = float(v)
                            except (ValueError, TypeError):
                                detailed[k] = 0.0
                        elif k in INT_FIELDS:
                            try:
                                detailed[k] = int(v)
                            except (ValueError, TypeError):
                                detailed[k] = 0
                        else:
                            detailed[k] = v
                    return detailed
        # If not found
        return None

